// The job order, flattened for the agent and kept for the post-back.
//
// Two fields were being thrown away here, and both of them are the difference
// between a contractor and a chat window.
//
//   b.log        what has already happened on THIS job, including the user's
//                answer to the question this worker asked last night. Without
//                it every dispatch was byte-identical, so the agent re-asked a
//                question it had already been given the answer to — every
//                night, for as long as anybody kept answering.
//   who.working  the user's working file: how they deliver, what they charge,
//                what they will not do. Research written from a five-string
//                offer comes back generic however good the model is, because
//                there is nothing specific for it to be specific about.
const b = $input.first().json.body || {};

if (!b.commission_id || !b.result_url) {
  throw new Error('No commission_id or result_url. If result_url is null, set NEXT_PUBLIC_COPILOT_SITE_URL on the app — without it the app cannot tell the worker where to report.');
}

const who = b.who || {};
const offer = who.offer || {};
const plan = Array.isArray(b.plan) ? b.plan : [];
const log = Array.isArray(b.log) ? b.log : [];

// Oldest first: it is a transcript, and "which of the three? / the second one"
// only reads in that order.
const history = log
  .map((e) => `  [${e.kind}${e.step ? ` step ${e.step}` : ''}] ${e.summary}`)
  .join('\n');

const answered = log.filter((e) => e.kind === 'answered');

const task = [
  `OBJECTIVE: ${b.objective}`,
  b.why ? `WHY IT MATTERS: ${b.why}` : null,
  b.goal ? `IT IS MEANT TO MOVE: ${b.goal.title}${b.goal.target ? ` (target ${b.goal.target}${b.goal.unit || ''})` : ''}` : null,
  '',
  `WHO THEY ARE: ${who.name || 'unknown'}${who.headline ? ` — ${who.headline}` : ''}`,
  offer.sells ? `WHAT THEY SELL: ${offer.sells}${offer.for_who ? ` for ${offer.for_who}` : ''}${offer.problem ? `, solving: ${offer.problem}` : ''}` : null,
  who.target_area || who.location ? `WHERE: ${who.target_area || who.location}` : null,
  who.target_segments?.length ? `WHO THEY TARGET: ${who.target_segments.join(', ')}` : null,
  // Only what they wrote or confirmed. Absent for an account with no file.
  who.working ? `\nWHAT THEY HAVE TOLD THE APP ABOUT THEIR WORK:\n${who.working}` : null,
  '',
  plan.length
    ? `THE PLAN SO FAR:\n${plan.map((s) => `  ${s.n}. [${s.state}] ${s.do}`).join('\n')}`
    : 'NO PLAN YET — propose one of 2 to 5 steps as part of your answer.',
  '',
  history
    ? `WHAT HAS ALREADY HAPPENED ON THIS JOB (oldest first):\n${history}`
    : 'NOTHING HAS HAPPENED YET — this is the first run.',
  answered.length
    ? `\nTHE OWNER HAS ANSWERED YOU. Their answer is in the log above under [answered]. Act on it. Do NOT ask it again in different words — that is the single most expensive thing you can do here.`
    : null,
  '',
  `YOU MAY: ${b.may}. ${b.may_autonomously
    ? 'You may carry this out yourself.'
    : 'You may NOT carry this out. Research and prepare it, then report what you WOULD do as a needs_you event and stop.'}`,
  `TIME BUDGET: about ${b.budget_minutes} minutes of work.`,
].filter((line) => line !== null && line !== undefined).join('\n');

return [{ json: {
  task,
  commission_id: b.commission_id,
  result_url: b.result_url,
  plan,
  budget_minutes: b.budget_minutes || 60,
} }];

// Hold the agent to the same floor the app applies on arrival, so a malformed
// answer fails here where it is visible rather than silently landing as zero
// accepted events.
//
// 'answered' is deliberately NOT in this list. It is the user's reply to a
// needs_you, written only when they answer in the app — a worker that could
// post one would be answering its own question and clearing its own gate, which
// is the same rule that makes `status` below unsendable.
const KINDS = ['planned', 'worked', 'found', 'needs_you', 'blocked', 'done', 'failed'];
const STATES = ['todo', 'doing', 'done', 'blocked'];
const built = $('Build the task').first().json;

let out = $input.first().json.output ?? $input.first().json.text ?? '';
if (typeof out === 'string') {
  const fenced = out.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '');
  const start = fenced.indexOf('{');
  const end = fenced.lastIndexOf('}');
  try { out = JSON.parse(start >= 0 && end > start ? fenced.slice(start, end + 1) : fenced); }
  catch { out = { events: [{ kind: 'failed', summary: `The worker did not return JSON: ${String(fenced).slice(0, 200)}` }] }; }
}

const str = (v, max) => (typeof v === 'string' && v.trim() ? v.trim().slice(0, max) : undefined);

const artifact = (a) => {
  if (!a || typeof a !== 'object') return null;
  const label = str(a.label, 40);
  const value = str(a.value, 4000);
  if (!label || !value) return null;
  const raw = str(a.href, 1000);
  // http(s) only. The app drops anything else, and so should this.
  const href = raw && /^https?:\/\//i.test(raw) ? raw : null;
  const kind = ['link', 'text', 'message'].includes(a.kind) ? a.kind : (href ? 'link' : 'text');
  if (kind === 'link' && !href) return null;
  return { kind, label, value, href };
};

let events = (Array.isArray(out.events) ? out.events : [])
  .map((e) => {
    const kind = KINDS.includes(e?.kind) ? e.kind : null;
    const summary = str(e?.summary, 300);
    if (!kind || !summary) return null;
    return { kind, summary, step: Number.isFinite(e?.step) ? Math.trunc(e.step) : null, artifact: artifact(e?.artifact) };
  })
  .filter(Boolean)
  .slice(0, 20);

// A tool that fell over is not a question for the owner.
//
// The app now renders needs_you as "Your answer" with a text box, and blocked
// as "It could not finish" with a retry. A model that labels a dead search tool
// as needs_you therefore puts a text box in front of somebody and asks them to
// reply to a 500. The system message says which to use; this is the backstop,
// because the cost of getting it wrong lands on the user rather than here.
const TOOL_TROUBLE = /\b(tool|search|fetch|request|http|api|timeout|timed out|rate.?limit|5\d\d error|internal error)\b/i;
const CANNOT = /\b(could not|couldn't|cannot|can't|unable to|failed to)\b/i;
events = events.map((e) => (
  e.kind === 'needs_you' && TOOL_TROUBLE.test(e.summary) && CANNOT.test(e.summary)
    ? { ...e, kind: 'blocked' }
    : e
));

const plan = (Array.isArray(out.plan) ? out.plan : [])
  .map((s, i) => {
    const doing = str(s?.do ?? s?.step, 200);
    if (!doing) return null;
    return { n: Number.isFinite(s?.n) ? Math.trunc(s.n) : i + 1, do: doing, state: STATES.includes(s?.state) ? s.state : 'todo' };
  })
  .filter(Boolean)
  .slice(0, 12);

if (!events.length) {
  events.push({ kind: 'worked', summary: 'Looked, and had nothing worth reporting this run.', step: null, artifact: null });
}

// `status` is deliberately NOT sent: the app computes it from the events and
// ignores anything a worker claims about its own state.
return [{ json: { result_url: built.result_url, payload: { events, ...(plan.length ? { plan } : {}) } } }];

// The agent died. Say so in the app rather than leaving the job reading
// 'Nothing back yet' until somebody gives up on it.
//
// 'blocked' rather than 'failed' on purpose: both put the job in front of the
// user, but the app reads a blocked job that carries no question as something
// the WORKER could not finish, and offers a retry instead of a text box. A run
// that died on an infrastructure problem is exactly that.
const built = $('Build the task').first().json;
const err = $input.first().json;
const why = err?.error?.message || err?.message || 'The worker failed with no message.';
return [{ json: {
  result_url: built.result_url,
  payload: { events: [{ kind: 'blocked', summary: String(why).slice(0, 300), step: null, artifact: null }] },
} }];
